INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'la-foto-fija', 'La Foto Fija', 'Dinámica de congelamiento fotográfico y dramatización exprés donde los scouts representan una escena fija que cobra vida al ''clic''.', '<h2>📜 Descripción de La Foto Fija</h2>
<p><b>La Foto Fija</b> es una dinámica de expresión kinésica, congelamiento dramático e improvisación teatral instantánea. Organizados por patrullas, los scouts componen una ''fotografía congelada'' tridimensional que representa un momento icónico de campamento (ej. <i>''El izamiento de la bandera en la mañana''</i>, <i>''La llegada a la cumbre tras una larga marcha''</i> o <i>''El momento en que se apaga la fogata''</i>).</p>
<p>Un participante o dirigente actúa de <i>''Fotógrafo''</i>. Al grito de <i>''¡Foto fija!''</i>, la patrulla congela su expresión y postura física de inmediato. Cuando el fotógrafo presiona el disparador imaginario exclamando <i>''¡Clic!''</i>, la escena congelada ''cobra vida'' durante exactamente 5 segundos, mostrando la acción previa y posterior a la toma fotográfica con diálogo y movimiento, para volver a congelarse al instante.</p>
<p>Esta actividad ejercita el control corporal, la soltura dramática, la asociación rápida de ideas y el trabajo cooperativo en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega La Foto Fija?</h2>
<p>Para llevar a cabo la dinámica con entusiasmo, dinamismo y sorpresa, los dirigentes y guías deben seguir estos pasos:</p>
<ul>
  <li><b>Asignación de la Fotografía:</b> Cada patrulla recibe un título de escena scout para representar.</li>
  <li><b>Composición del Encuadre:</b> Los integrantes se ubican en distintas alturas y posturas (algunos agachados, otros de pie) para armar una composición visualmente atractiva.</li>
  <li><b>El Congelamiento ''Foto Fija'':</b> A la señal del animador, todos los integrantes quedan completamente inmóviles como una estatua fotográfica.</li>
  <li><b>El Disparo de la Cámara (''¡Clic!''):</b> Al escucharse el <i>''¡Clic!''</i>, la estatua cobra vida durante 5 segundos de acción y diálogo rápido.</li>
  <li><b>El Re-congelamiento y Aplauso:</b> Transcurridos los 5 segundos, la patrulla vuelve a la inmovilidad total para recibir los aplausos del grupo.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de La Foto Fija</h2>
<p>La actividad valora la expresividad kinésica y el humor escénico en el Tally:</p>
<ul>
  <li><b>Mayor Expresividad de la Foto:</b> Otorgar 5 puntos a la patrulla que arme la pose fija más ingeniosa y expresiva.</li>
  <li><b>Espontaneidad del Momento Vivo:</b> Otorgar 3 puntos al equipo cuyos 5 segundos de acción sean los más divertidos e imprevistos.</li>
  <li><b>Inmovilidad de Encuadre:</b> Otorgar 3 puntos al grupo que sostenga el congelamiento sin pestañear ni moverse.</li>
</ul>', '/uploads/la-foto-fija.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Sin Materiales"], "objetivos": ["Fomentar la comunicación e interpretación", "Estimular la agilidad mental", "Desarrollar la motricidad", "Trabajo en equipo"], "justificacion_areas": "La Foto Fija potencia la creatividad al exigir la conceptualización espacial de una escena congelada y su animación instantánea en 5 segundos. Desarrolla la sociabilidad al afianzar la sincronización en equipo, la soltura escénica y el trabajo coordinado en patrulla desde Manada hasta Clan.", "variaciones": "<b>Foto Fija de Álbum Histórico:</b> Recrear una fotografía real del primer campamento scout en Brownsea de 1907.<br><b>Foto Fija con Filtro de Cámara Lenta:</b> Ejecutar los 5 segundos de vida en cámara lenta extrema.<br><b>Foto Fija Nocturna con Flash de Linternas:</b> Iluminar la foto congelada con destellos de linterna en la oscuridad.", "recomendaciones": "Promover poses seguras y equilibradas. Estimular el sentido del humor.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Participando en la composición de la foto fija y actuando en los 5 segundos de vida."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando el congelamiento instantáneo y los tiempos del juego."}, {"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "unidad": "Manada", "texto": "En las actividades que hago se nota lo que pienso y siento.", "como_se_cumple": "Expresando emociones y gestos divertidos en la escena fotográfica."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Colaborando alegremente en el equipo durante la toma de la foto."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Liderando composiciones fotográficas dramáticas en la patrulla."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo el respeto y la inclusión de todas las integrantes en la pose."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando la composición espacial desde ángulos estéticos variados."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo el trabajo limpio y la alegría en la actuación."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Aportando creatividad kinésica en las representaciones de la Tropa."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando disciplina y respeto por el tiempo de congelamiento."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Diseñando encuadres fotográficos complejos e improvisaciones de patrulla."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y fraternidad en el equipo de Tropa."}, {"id": "d252cb51-c224-4528-90b3-e0288aa343dd", "area": "Creatividad", "unidad": "Avanzada", "texto": "Comparto con los demás mis inquietudes, aspiraciones y creaciones artísticas.", "como_se_cumple": "Compartiendo con la Avanzada la dirección dramática de las imágenes vivas."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Promoviendo el liderazgo integrador y la expresión artística colectiva."}, {"id": "91e60eba-e267-4d1a-b27b-ef61a7b03b31", "area": "Creatividad", "unidad": "Clan", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Fomentando el arte escénico y la hermandad alegre en el Clan Rover."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Viviendo la fraternidad scout y la coordinación en proyectos compartidos."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

